 const operatingExpenses=(readLiveData().expenses||[]).filter(expense=>expense.status!=='cancelada').filter(expense=>{const date=new Date(`${expense.competencia}T12:00:00`);return date>=competenceStart&&date<=competenceEnd}).reduce((sum,expense)=>sum+(Number(expense.valor)||0),0);
