 syncCategoryFilter();const live=readLiveData(),products=(live.products||[]).filter(p=>p&&p.ativo!==false),filtered=state.category==='all'?products:products.filter(p=>itemCategory(p)===state.category),units=filtered.reduce((s,p)=>s+(p.kind==='acessorio'?(Number(p.quantidade)||0):1),0),stockCost=filtered.reduce((s,p)=>s+(Number(p.custo)||0)*(p.kind==='acessorio'?(Number(p.quantidade)||0):1),0),stockRetail=filtered.reduce((s,p)=>s+(Number(p.venda)||0)*(p.kind==='acessorio'?(Number(p.quantidade)||0):1),0),period='Período selecionado',K=(label,value,icon,color,area,description,details)=>[label,value,period,icon,color,area,description,details];
