function openListModal(category,title,value,description,html){document.querySelector('#metricModalCategory').textContent=category;document.querySelector('#metricModalTitle').textContent=title;document.querySelector('#metricModalValue').textContent=value;document.querySelector('#metricModalDescription').textContent=description;document.querySelector('#metricModalDetails').innerHTML=html||'<div class="modal-empty">Nenhum registro encontrado.</div>';const pager=document.querySelector('#metricModalPagination');pager.hidden=true;pager.innerHTML='';document.querySelector('#metricModal').hidden=false;document.body.classList.add('modal-open')}
function saleValue(sale){return Number(sale.total)||activePaymentsForDashboard(sale).reduce((sum,p)=>sum+(Number(p.valorBase??p.valor)||0),0)}
function activePaymentsForDashboard(sale){return(sale.pagamentos||[]).filter(p=>p.status!=='estornado')}
function liveSales(){return(readLiveData().sales||[]).filter(s=>s&&s.status!=='estornado').sort((a,b)=>new Date(b.criadoEm)-new Date(a.criadoEm))}
const categoryPalette=['#ff7a33','#f2b84b','#3fce8e','#65a9ff','#b58cff','#f2545b','#38bdf8','#a3e635','#fb7185','#c084fc'];
function categorySlug(value){return String(value||'outros').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')||'outros'}
function categoryLabel(item){const product=item.productSnapshot||item,kind=String(product.kind||item.kind||'').toLowerCase(),specific=String(product.categoria||'').trim();if(kind==='acessorio')return specific&&!specific.toLowerCase().includes('troca')?specific:'Acessórios';if(kind==='celular')return'Celulares';if(kind==='servico'||item.tipo==='avulso'||item.tipo==='servico')return'Serviços';if(kind==='protecao'||item.tipo==='protecao')return'Proteção';if(specific&&!specific.toLowerCase().includes('troca'))return specific;return kind?kind.charAt(0).toUpperCase()+kind.slice(1):'Outros'}
