function dashboardCategories(){const source=[...(readLiveData().products||[]),...filteredLiveSales().flatMap(sale=>sale.itens||[])],map=new Map();source.forEach(item=>{const label=categoryLabel(item),key=categorySlug(label);if(!map.has(key))map.set(key,{key,label})});return[...map.values()].sort((a,b)=>a.label.localeCompare(b.label,'pt-BR')).map((item,index)=>({...item,color:categoryPalette[index%categoryPalette.length]}))}
function syncCategoryFilter(){const select=document.querySelector('#category'),selected=select.value,categories=dashboardCategories();select.innerHTML='<option value="all">Todas as categorias</option>'+categories.map(item=>`<option value="${item.key}">${item.label}</option>`).join('');select.value=categories.some(item=>item.key===selected)?selected:'all';state.category=select.value}
function categorySalesItems(category){const rows=[];filteredLiveSales().forEach(sale=>(sale.itens||[]).filter(item=>item.status!=='estornado').forEach(item=>{const qty=Number(item.quantidade)||1,unit=Number(item.vendaUnit)||0,total=qty*unit;if(itemCategory(item)===category&&total>0)rows.push({sale,item,name:item.nome||item.productSnapshot?.modelo||'Item sem nome',qty,unit,total})}));return rows}
function categoryTotals(){return dashboardCategories().map(item=>({category:item.key,label:item.label,color:item.color,total:categorySalesItems(item.key).reduce((sum,x)=>sum+x.qty,0)})).filter(item=>item.total>0)}
