const LABELS_DASH={pix:'Pix',cartao_credito:'Cartão de crédito',cartao_debito:'Cartão de débito',dinheiro:'Dinheiro',troca:'Troca'};
function openCategoryModal(category){const items=categorySalesItems(category),grouped=Object.values(items.reduce((acc,row)=>{const key=row.name.trim().toLocaleLowerCase('pt-BR');if(!acc[key])acc[key]={name:row.name,qty:0,total:0,sales:new Set()};acc[key].qty+=row.qty;acc[key].total+=row.total;acc[key].sales.add(row.sale.id);return acc},{})).sort((a,b)=>b.total-a.total),total=grouped.reduce((sum,x)=>sum+x.total,0),label=dashboardCategories().find(item=>item.key===category)?.label||'Outros',html=grouped.map(row=>`<div class="modal-list-row"><div><strong>${row.name}</strong><span>${row.qty} unidade${row.qty===1?'':'s'} · ${row.sales.size} venda${row.sales.size===1?'':'s'}</span></div><b>${money(row.total)}</b></div>`).join('');openListModal('RECEITA POR CATEGORIA',label,`${grouped.length} itens · ${money(total)}`,'Itens efetivamente vendidos, com valor maior que zero.',html)}
function openCategoryOverview(){const totals=categoryTotals(),total=totals.reduce((sum,x)=>sum+x.total,0),html=totals.filter(x=>x.total>0).map(x=>`<button type="button" class="modal-list-row modal-category-link" data-open-category="${x.category}"><div><strong>${x.label}</strong><span>${total?(x.total/total*100).toFixed(1):0}% dos itens</span></div><b>${x.total} un.</b></button>`).join('');openListModal('DISTRIBUIÇÃO','Itens vendidos por categoria',`${total} itens`,'Distribuição pela quantidade de unidades vendidas.',html)}
function openDailySales(dayIndex){const labels=['Segunda-feira','Terça-feira','Quarta-feira','Quinta-feira','Sexta-feira','Sábado','Domingo'],jsDay=(dayIndex+1)%7,sales=liveSales().filter(s=>new Date(s.criadoEm).getDay()===jsDay),total=sales.reduce((sum,s)=>sum+saleValue(s),0);openListModal('VENDAS POR DIA',labels[dayIndex],`${sales.length} vendas · ${money(total)}`,'Vendas registradas nesse dia da semana.',saleRows(sales))}
function movementEntries(){const entries=[];(readLiveData().sales||[]).forEach(sale=>{const payments=(sale.pagamentos||[]);if(!payments.length)entries.push({sale,payment:null,direction:sale.status==='estornada'?'saida':'entrada',type:sale.status==='estornada'?'estorno':'venda',value:Number(sale.total)||0,date:sale.criadoEm});payments.forEach((payment,index)=>{const reversed=payment.status==='estornado'||sale.status==='estornada',trade=payment.forma==='troca';entries.push({sale,payment,paymentIndex:index,direction:reversed?'saida':'entrada',type:reversed?'estorno':trade?'troca':'venda',value:Number(payment.valorBase??payment.valor)||0,date:payment.estornadoEm||sale.criadoEm})})});return entries.sort((a,b)=>new Date(b.date)-new Date(a.date))}
function movementRowsHtml(rows){return rows.map((entry,index)=>{const direction=entry.direction==='entrada'?'Entrada':'Saída',type=entry.type==='troca'?'Troca':entry.type==='estorno'?'Estorno':'Venda',payment=entry.payment?LABELS_DASH[entry.payment.forma]||entry.payment.forma:'Sem pagamento';return`<button type="button" class="modal-list-row movement-row movement-${entry.type}" data-movement-key="${entry.sale.id}|${entry.paymentIndex??-1}"><div><strong><span class="movement-badge ${entry.direction}">${direction}</span><span class="movement-type ${entry.type}">${type}</span> ${entry.sale.cliente?.nome||'Consumidor'}</strong><span>${new Date(entry.date).toLocaleString('pt-BR')} · ${payment}</span></div><b class="${entry.direction}">${entry.direction==='entrada'?'+':'−'} ${money(entry.value)}</b></button>`}).join('')}
let movementPage=1;const movementPageSize=8;
function openMovements(page=1){const rows=movementEntries(),pages=Math.max(1,Math.ceil(rows.length/movementPageSize));movementPage=Math.min(Math.max(1,page),pages);const slice=rows.slice((movementPage-1)*movementPageSize,movementPage*movementPageSize),balance=rows.reduce((sum,x)=>sum+(x.direction==='entrada'?x.value:-x.value),0);openListModal('ATIVIDADE RECENTE','Todas as movimentações',`${rows.length} registros · saldo ${money(balance)}`,'Entradas, saídas, vendas, trocas e estornos em ordem cronológica.',movementRowsHtml(slice));const pager=document.querySelector('#metricModalPagination');pager.hidden=false;pager.innerHTML=`<button type="button" data-move-page="${movementPage-1}" ${movementPage===1?'disabled':''}>Anterior</button><span>Página ${movementPage} de ${pages}</span><button type="button" data-move-page="${movementPage+1}" ${movementPage===pages?'disabled':''}>Próxima</button>`}
function openMovementDetail(saleId,paymentIndex){const sale=(readLiveData().sales||[]).find(s=>String(s.id)===String(saleId));if(!sale)return;const payment=Number(paymentIndex)>=0?(sale.pagamentos||[])[Number(paymentIndex)]:null,reversed=payment?.status==='estornado'||sale.status==='estornada',type=reversed?'Estorno':payment?.forma==='troca'?'Troca':'Venda',value=payment?Number(payment.valorBase??payment.valor)||0:Number(sale.total)||0,items=(sale.itens||[]).filter(i=>i.status!=='estornado').map(item=>`<div class="modal-list-row"><div><strong>${item.quantidade||1}x ${item.nome||'Item'}</strong><span>${item.sub||item.kind||''}</span></div><b>${money((Number(item.vendaUnit)||0)*(Number(item.quantidade)||1))}</b></div>`).join(''),payments=(sale.pagamentos||[]).map(p=>`<div class="modal-list-row"><div><strong>${LABELS_DASH[p.forma]||p.forma}${p.bandeira?` · ${p.bandeira} ${p.parcelas||1}x`:''}</strong><span>${p.status==='estornado'?'Estornado':'Ativo'}${p.taxaPct?` · taxa ${p.taxaPct}%`:''}</span></div><b>${money(Number(p.valorBase??p.valor)||0)}</b></div>`).join('');document.querySelector('#movementDetailCategory').textContent=`${reversed?'SAÍDA':'ENTRADA'} · ${type.toUpperCase()}`;document.querySelector('#movementDetailTitle').textContent=sale.cliente?.nome||'Consumidor';document.querySelector('#movementDetailValue').textContent=`${reversed?'−':'+'} ${money(value)}`;document.querySelector('#movementDetailDescription').textContent=`Venda ${String(sale.id||'').slice(0,12)} · ${new Date(sale.criadoEm).toLocaleString('pt-BR')}`;document.querySelector('#movementDetailContent').innerHTML=`<h3>Itens relacionados</h3>${items||'<div class="modal-empty">Sem itens.</div>'}<h3>Pagamentos relacionados</h3>${payments||'<div class="modal-empty">Sem pagamentos.</div>'}`;document.querySelector('#movementDetailModal').hidden=false}
