function openMetricModal(kpi){document.querySelector('#metricModalCategory').textContent=kpi[5];document.querySelector('#metricModalTitle').textContent=kpi[0];document.querySelector('#metricModalValue').textContent=kpi[1];document.querySelector('#metricModalDescription').textContent=kpi[6];document.querySelector('#metricModalDetails').innerHTML=(kpi[7]||[]).map(x=>`<div><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('');document.querySelector('#metricModal').hidden=false;document.body.classList.add('modal-open')}
