function drawLine(rev,exp,labels){
  document.querySelector('#lineChart').setAttribute('viewBox','0 0 800 260');
  const all=[...rev,...exp],max=Math.max(1,Math.ceil(Math.max(...all)/10000)*10000),min=0,w=800,h=245,p=8;
  const pts=arr=>arr.map((v,i)=>`${p+i*(w-p*2)/(arr.length-1)},${h-(v-min)/(max-min)*(h-18)}`).join(' ');
  const rpts=pts(rev),epts=pts(exp),area=`${p},${h} ${rpts} ${w-p},${h}`;
  let grid='';for(let i=0;i<5;i++)grid+=`<line class="gridline" x1="0" y1="${i*h/4}" x2="800" y2="${i*h/4}"/>`;
  document.querySelector('#lineChart').innerHTML=`<defs><linearGradient id="areaGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#3fce8e" stop-opacity=".2"/><stop offset="1" stop-color="#3fce8e" stop-opacity="0"/></linearGradient></defs>${grid}<polygon class="area" points="${area}"/><polyline class="revenue-line" points="${rpts}"/><polyline class="expense-line" points="${epts}"/>${rev.map((v,i)=>`<circle class="dot-chart" cx="${p+i*(w-p*2)/(rev.length-1)}" cy="${h-v/max*(h-18)}" r="4" fill="#3fce8e"><title>${money(v)}</title></circle>`).join('')}`;
  document.querySelector('#yAxis').innerHTML=[max,max*.75,max*.5,max*.25,0].map(v=>`<span>${v>=1000?Math.round(v/1000)+'k':v}</span>`).join('');
  document.querySelector('#xAxis').innerHTML=labels.map(x=>`<span>${x}</span>`).join('');
}
