 const live=readLiveData(),users=live.userProfiles||[],start=commissionStart.value,end=commissionEnd.value;
 const sales=(live.sales||[]).filter(sale=>sale.criadoPor&&sale.status!=='estornada'&&(!start||String(sale.criadoEm).slice(0,10)>=start)&&(!end||String(sale.criadoEm).slice(0,10)<=end));
