 return[...userMap.values()].map(user=>{const userSales=sales.filter(sale=>String(sale.criadoPor)===String(user.id)),rows=movements.filter(item=>String(item.vendedorId)===String(user.id)),base=rows.reduce((sum,item)=>sum+Number(item.baseComissao||0),0),commission=rows.reduce((sum,item)=>sum+Number(item.valorComissao||0),0),rate=base?commission/base*100:0,userAdvances=advances.filter(item=>String(item.seller_id)===String(user.id)),advance=userAdvances.reduce((sum,item)=>sum+Number(item.amount||0),0);return{user,sales:userSales.length,base,rate,commission,advance,balance:commission-advance}}).filter(row=>row.advance>0)
