let financeOverviewLoading=false;
function financeWorkspaceDefaults(){const format=date=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Fortaleza'}).format(date),end=new Date(),start=new Date(end);start.setDate(start.getDate()-30);if(!financeEnd.value)financeEnd.value=format(end);if(!financeStart.value)financeStart.value=format(start)}
function renderFinanceOverview(movements){const active=movements.filter(item=>item.status==='ativo');state.financeRows=active;const entries=active.filter(item=>item.movement_type==='entrada').reduce((sum,item)=>sum+Number(item.amount||0),0),expenses=active.filter(item=>item.movement_type==='despesa').reduce((sum,item)=>sum+Number(item.amount||0),0),salesRevenue=(readLiveData().sales||[]).filter(sale=>sale&&sale.status!=='estornado').filter(sale=>{const parsed=new Date(sale.criadoEm),date=Number.isNaN(parsed.getTime())?'':parsed.toISOString().slice(0,10);return(!financeStart.value||date>=financeStart.value)&&(!financeEnd.value||date<=financeEnd.value)}).reduce((sum,sale)=>sum+saleValue(sale),0),balance=salesRevenue+entries-expenses;financeOverviewKpis.innerHTML=[['Receita de vendas',exactMoney(salesRevenue),'#3fce8e'],['Outras entradas',exactMoney(entries),'#3fce8e'],['Despesas',exactMoney(expenses),'#f2545b'],['Saldo realizado',exactMoney(balance),balance<0?'#f2545b':'#3fce8e']].map(item=>`<article class="kpi"><div class="kpi-top"><span>${item[0]}</span></div><strong style="color:${item[2]}">${item[1]}</strong></article>`).join('');const recent=[...active].sort((a,b)=>new Date(b.movement_date)-new Date(a.movement_date)).slice(0,10);financeOverviewRows.innerHTML=recent.length?recent.map(item=>`<tr><td>${new Date(`${item.movement_date}T12:00:00`).toLocaleDateString('pt-BR')}</td><td class="${item.movement_type==='entrada'?'commission-positive':'commission-negative'}">${item.movement_type==='entrada'?'Entrada':'Despesa'}</td><td>${escapeHtml(item.category)}</td><td>${escapeHtml(item.description)}</td><td>${escapeHtml(item.seller_name||'—')}</td><td class="${item.movement_type==='entrada'?'commission-positive':'commission-negative'}">${item.movement_type==='entrada'?'+':'−'} ${exactMoney(item.amount)}</td></tr>`).join(''):'<tr><td colspan="6" class="commission-empty">Nenhum lançamento financeiro no período.</td></tr>';financeOverviewCount.textContent=`${active.length} ${active.length===1?'lançamento':'lançamentos'}`;fitDashboardFrameHeight()}
async function loadFinanceOverview(){if(financeOverviewLoading)return;financeWorkspaceDefaults();financeOverviewLoading=true;financeOverviewKpis.innerHTML=Array.from({length:4},()=>'<article class="kpi"><span class="commission-skeleton" style="width:45%"></span><span class="commission-skeleton" style="width:70%;height:24px;margin-top:18px"></span></article>').join('');financeOverviewRows.innerHTML='<tr><td colspan="6"><span class="commission-skeleton"></span></td></tr>'.repeat(5);try{const result=await requestCommissionMovements({start:financeStart.value,end:financeEnd.value});renderFinanceOverview(result.movements||[])}catch(error){financeOverviewKpis.innerHTML='';financeOverviewRows.innerHTML=`<tr><td colspan="6" class="commission-empty commission-negative">${escapeHtml(error.message)}</td></tr>`}finally{financeOverviewLoading=false}}
function showFinanceSection(section){document.querySelectorAll('[data-finance-section]').forEach(button=>button.classList.toggle('active',button.dataset.financeSection===section));financeOverview.hidden=section!=='overview';financeOperations.hidden=section!=='movements';commissionView.hidden=section!=='advances';if(section==='overview')loadFinanceOverview();if(section==='advances')loadCommissionDashboard();fitDashboardFrameHeight()}function exportFinanceOverviewCsv(){const rows=[['Data','Tipo','Categoria','Descrição','Responsável','Valor','Status'],...(state.financeRows||[]).map(item=>[item.movement_date,item.movement_type,item.category,item.description,item.seller_name||'',Number(item.amount||0),item.status])],csv=rows.map(row=>row.map(value=>`"${String(value??'').replaceAll('"','""')}"`).join(';')).join('\n'),link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));link.download=`financeiro-${financeStart.value}-${financeEnd.value}.csv`;link.click();URL.revokeObjectURL(link.href);toast('Financeiro exportado em CSV')}function exportCommissionCsv(){const rows=[['Usuário','E-mail','Vendas','Lucro comissionável','Percentual','Comissão','Vales','Saldo'],...state.commissionRows.map(row=>[row.user.full_name||row.user.email,row.user.email||'',row.sales,row.base,row.rate,row.commission,row.advance,row.balance])],csv=rows.map(row=>row.map(value=>`"${String(value).replaceAll('"','""')}"`).join(';')).join('\n'),link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}));link.download=`comissoes-e-vales-${commissionStart.value}-${commissionEnd.value}.csv`;link.click();URL.revokeObjectURL(link.href)}applyStoreBrand();
document.querySelectorAll('select').forEach(x=>x.addEventListener('change',render));
const ChartModal={
 element:null,
 ensure(){if(this.element)return this.element;const modal=document.createElement('div');modal.className='chart-modal';modal.hidden=true;modal.innerHTML='<div class="chart-modal-backdrop" data-close-chart-modal></div><section class="chart-modal-card" role="dialog" aria-modal="true" aria-labelledby="chartModalTitle"><button class="chart-modal-close" type="button" data-close-chart-modal aria-label="Fechar">&times;</button><div class="chart-modal-content"></div></section>';document.body.append(modal);modal.addEventListener('click',event=>{if(event.target.closest('[data-close-chart-modal]'))this.close()});this.element=modal;return modal},
 open(card){const modal=this.ensure(),clone=card.cloneNode(true);clone.querySelectorAll('[id]').forEach(node=>node.removeAttribute('id'));clone.classList.add('chart-modal-chart');const content=modal.querySelector('.chart-modal-content');content.replaceChildren(clone);const title=clone.querySelector('h3');if(title)title.id='chartModalTitle';modal.hidden=false;document.body.classList.add('chart-modal-open')},
 close(){if(!this.element)return;this.element.hidden=true;this.element.querySelector('.chart-modal-content').replaceChildren();document.body.classList.remove('chart-modal-open')}
};
document.querySelector('.chart-grid').addEventListener('click',event=>{const target=event.target.closest('.chart-wrap,.donut');if(!target)return;event.stopPropagation();ChartModal.open(target.closest('.card'))});
document.querySelector('#dailySalesCard').addEventListener('click',event=>{if(!event.target.closest('#bars'))return;event.stopPropagation();ChartModal.open(event.currentTarget)});
document.querySelector('#clearFilters').addEventListener('click',()=>{document.querySelector('#period').value='30';document.querySelector('#category').value='all';document.querySelector('#compare').value='previous';render();toast('Filtros redefinidos')});
document.querySelector('#refresh').addEventListener('click',()=>{render();toast('Dados atualizados agora')});
document.querySelector('#printDashboard').addEventListener('click',()=>window.print());
document.querySelector('#exportBtn').addEventListener('click',()=>{const rows=['Indicador,Valor',...Array.from(document.querySelectorAll('.kpi')).map(k=>`"${k.querySelector('.kpi-top span').textContent}","${k.querySelector('strong').textContent}"`)];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));a.download='relatorio-dashboard.csv';a.click();URL.revokeObjectURL(a.href);toast('Relatório exportado')});
document.querySelectorAll('.nav [data-view]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.nav [data-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.view=b.dataset.view;render()}));
document.querySelector('#kpis').addEventListener('click',e=>{const card=e.target.closest('[data-kpi]');if(card)openMetricModal(state.currentKpis[Number(card.dataset.kpi)])});
document.querySelector('#kpis').addEventListener('keydown',e=>{const card=e.target.closest('[data-kpi]');if(card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openMetricModal(state.currentKpis[Number(card.dataset.kpi)])}});
document.querySelector('#categoryRevenueCard').addEventListener('click',e=>{if(!e.target.closest('[data-category],.donut'))openCategoryOverview()});
document.querySelector('#metricModalDetails').addEventListener('click',e=>{const category=e.target.closest('[data-open-category]');if(category)openCategoryModal(category.dataset.openCategory);const movement=e.target.closest('[data-movement-key]');if(movement){const [saleId,paymentIndex]=movement.dataset.movementKey.split('|');openMovementDetail(saleId,paymentIndex)}});
document.querySelector('#transactions').addEventListener('click',e=>{const movement=e.target.closest('[data-movement-key]');if(movement){e.stopPropagation();const [saleId,paymentIndex]=movement.dataset.movementKey.split('|');openMovementDetail(saleId,paymentIndex)}});
document.querySelectorAll('[data-close-movement]').forEach(x=>x.addEventListener('click',closeMovementDetail));
document.querySelector('#categoryList').addEventListener('click',e=>{const item=e.target.closest('[data-category]');if(item){e.stopPropagation();openCategoryModal(item.dataset.category)}});
document.querySelector('#movementsCard').addEventListener('click',e=>{if(state.view!=='inventory'&&!e.target.closest('[data-close-modal]'))openMovements(1)});
document.querySelector('#metricModalPagination').addEventListener('click',e=>{const button=e.target.closest('[data-move-page]');if(button&&!button.disabled)openMovements(Number(button.dataset.movePage))});
document.querySelectorAll('[data-close-modal]').forEach(x=>x.addEventListener('click',closeMetricModal));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeMetricModal();ChartModal.close()}});
document.querySelector('#financeWorkspace').addEventListener('click',event=>{const button=event.target.closest('[data-finance-section]');if(button)showFinanceSection(button.dataset.financeSection)});
document.querySelector('#applyFinanceOverview').addEventListener('click',loadFinanceOverview);document.querySelector('#printFinanceOverview').addEventListener('click',()=>window.print());document.querySelector('#exportFinanceOverview').addEventListener('click',exportFinanceOverviewCsv);
document.querySelector('#applyCommissionFilters').addEventListener('click',()=>{state.commissionPage=1;state.advancePage=1;loadCommissionDashboard()});
document.querySelector('#commissionSearch').addEventListener('input',()=>{state.commissionPage=1;state.advancePage=1;renderCommissionDashboard()});
document.querySelector('#commissionView').addEventListener('click',event=>{const button=event.target.closest('[data-commission-page]');if(!button||button.disabled)return;if(button.dataset.commissionPage==='users')state.commissionPage=Number(button.dataset.page);else state.advancePage=Number(button.dataset.page);renderCommissionDashboard()});
document.querySelector('#printCommissions').addEventListener('click',()=>window.print());
document.querySelector('#exportCommissions').addEventListener('click',exportCommissionCsv);
render();


// Encaminha as operacoes financeiras entre o relatorio aninhado e a tela autenticada.
const financeRelay=typeof BroadcastChannel!=='undefined'?new BroadcastChannel('dashboard-finance'):null;
function reportFinanceWindows(){return[...document.querySelectorAll('#reportView iframe,#financeOperations iframe')].map(frame=>frame.contentWindow).filter(Boolean)}
function deliverFinanceResponse(payload){reportFinanceWindows().forEach(target=>target.postMessage(payload,location.origin))}
window.addEventListener('message',event=>{if(event.origin!==location.origin)return;const payload=event.data;if(payload?.type==='dashboard-finance-request'){if(window.parent!==window)window.parent.postMessage(payload,location.origin);else financeRelay?.postMessage(payload)}else if(payload?.type==='dashboard-finance-response'){acceptCommissionResponse(payload);deliverFinanceResponse(payload)}});
if(financeRelay)financeRelay.onmessage=event=>{if(event.data?.type==='dashboard-finance-response'){acceptCommissionResponse(event.data);deliverFinanceResponse(event.data)}};

